      "faq.q1.q": "译文是否已经完全校对？",
      "faq.q1.a": "尚未。当前译文中绝大部分由 AI 生成，仍在持续改进；应用也邀请大家共同参与校对与术语统一。",
      "faq.q2.q": "我可以贡献修订吗？",
      "faq.q2.a": "可以。注册并登录后，双击段落译文即可编辑并提交校对建议（经后台审核后将发布到后续数据库版本）。",
      "faq.q3.q": "是否支持离线使用？",
      "faq.q3.a": "支持。内容存储在本地 SQLite 数据库中；可离线使用，并在联网时获取更新。",
      "faq.q4.q": "应用内数据库下载失败怎么办？",
      "faq.q4.a":
        "使用上述数据库下载数据库包并导入应用；未使用应用商店时，可通过上述下载链接获取 Android APK 以及 Linux 安装包。",

