        "ཞུ་དག་ལ་ཞུགས་མཁན་སྤྱོད་མཁན་གྱིས་ཡིག་སྒམ་དང་སྤྱོད་མཁན་མིང་གི་ཐོ་འགོད་བྱེད་དགོས། དེ་ལས་གཞན་སྤྱོད་མཁན་གྱི་སྒེར་གསང་གཞན་དག་མི་བསྡུ།",
