      "online.title": "Tipiṭaka Translation (དྲ་ཐོག)",
      "online.subtitle":
        "OpenTipitaka མཉེན་ཆས་དང་མཉམ་དུ་ལས་གཞིའི་ནང་དོན་དྲ་ངོས་སུ་ཀློག་པའི་ཐབས་གཙོ་བོ།",
