      "online.cta": "དྲ་ངོས་ཁ་ཕྱེ",

      "features.title": "ཁྱད་ཆོས་གཙོ་བོ།",
      "features.subtitle": "གཏིང་ཟབ་པའི་སློབ་སྦྱོང་དང་ཡུན་རིང་གི་ཀློག་འདོན་ལ་དམིགས་ནས་ལེགས་བཅོས་བྱས་ཡོད། མགྱོགས་མྱུར་མཛུབ་སྟོན་དང་། ཡིག་སྒྱུར་མང་པོ་མཉམ་སྒྲིག་ཀློག་འདོན། ཞུ་དག་བདེ་བླག་བཅས་ཀྱི་ཁྱད་ཆོས་ཡོད།",
      "features.parallel.title": "ཡིག་སྒྱུར་མང་པོ་བསྡུར་ནས་ཀློག་པ།",
      "features.parallel.body": "པ་ལིའི་མ་ཕྱི་དང་སྐད་རིགས་མང་པོའི་ཡིག་སྒྱུར་དུམ་བུ་རེ་རེ་བཞིན་མཉམ་དུ་སྟོན་པ་དང་། སྟོན་འདོད་པའི་སྐད་རིགས་རང་དབང་གིས་འདེམས་ཆོག",
      "features.search.title": "ཡོངས་རྫོགས་འཚོལ་བ།",
      "features.search.body": "པ་ལིའི་མ་ཕྱི་དང་ཡིག་སྒྱུར་འཚོལ་བར་རྒྱབ་སྐྱོར་བྱེད་པ་དང་། དེབ་འདི་དང་དེབ་ཡོངས་རྫོགས་ཀྱི་ཁྱབ་ཁོངས་འདེམས་ཆོག་པ་མ་ཟད། ཚིག་གྲུབ་འཚོལ་བར་ཡང་རྒྱབ་སྐྱོར་བྱེད།",
      "features.proofread.title": "ཡིག་སྒྱུར་རྩོམ་སྒྲིག་དང་ཞུ་དག",
      "features.proofread.body": "ཡིག་སྒྱུར་གྱི་དུམ་བུར་ཐེངས་གཉིས་བརྡབ་ན་རྩོམ་སྒྲིག་བྱེད་པའི་སྒེའུ་ཁུང་འཆར་བ་དང་། ཐོ་འགོད་བྱས་རྗེས་ཞུ་དག་གི་བསམ་འཆར་སྤྲད་དེ་མཉམ་དུ་སྐྲུན་ཆོག",
      "features.nav.title": "མགྱོགས་མྱུར་མཛུབ་སྟོན་དང་མཆོང་སྐྱོད།",
      "features.nav.body": "ཏི་པི་ཊ་ཀའི་དཀར་ཆག་དང་དེབ་ནང་གི་ས་བཅད་དཀར་ཆག དུམ་བུའི་ཨང་གྲངས་དང་ཤོག་གྲངས་མི་འདྲ་བའི་ཐོག་ནས་མཆོང་སྐྱོད་བྱེད་པར་རྒྱབ་སྐྱོར་བྱེད།",
      "features.dict.title": "ཚིག་མཛོད་ལས་ཀའི་རྒྱུད་རིམ།",
      "features.dict.body": "པ་ལིའི་ཚིག་ལ་གནོན་པའམ་ཚིག་མཛོད་ནང་འཇུག་ནས་འཚོལ། ཉེ་མཚུངས་འཚོལ་བས་དབྱངས་རིང་ཐུང་། ṭ/t། ḍ/d། ḷ/l། སྣ་སྒྲའི་རྟགས་ཁ་ཤས་ལ་ཕན།",
      "features.split.title": "རྟགས་མང་པོ་དང་བརྙན་བགོ་བ།",
      "features.split.body": "དེབ་མང་པོ་མཉམ་དུ་འབྱེད་ཆོག་པ་དང་། བརྙན་ཆེ་བའི་སྟེང་དུ་མང་པོ་མཉམ་དུ་བགོ་ཆོག་ལ། བཀོད་པ་རང་འགུལ་གྱིས་ཉར་ཚགས་བྱེད།",
      "features.tts.title": "རང་འགུལ་འགྲིལ་བ་དང་ཡིག་སྒྱུར་ཀློག་སྒྲ།",
      "features.tts.body": "ཡིག་ཆ་རིང་པོ་ཀློག་སྐབས་རང་འགུལ་གྱིས་འགྲིལ་བ་དང་། དུམ་བུའི་ཡིག་སྒྱུར་ཀློག་པ་མ་ཟད་བརྙན་འཕྲིན་གྱི་ཚོད་འཛིན་ལའང་རྒྱབ་སྐྱོར་བྱེད།",
      "features.script.title": "པ་ལིའི་བྲིས་གཟུགས་འདྲ་མིན་།",
      "features.script.body": "པ་ལིའི་བྲིས་གཟུགས་མི་འདྲ་བ་སྟོན་པར་རྒྱབ་སྐྱོར་བྱེད（རོ་མན་དང་། ལྷ་ཡིག ཐཱའི་ཡིག མཐིལ་ཡིག བོད་ཡིག་སོགས）།",

      "download.title": "ཕབ་ལེན་དང་གཞི་གྲངས",
