      "support.feedbackIntro":
        "OpenTipitaka མཉེན་ཆས་སམ་དྲ་ངོས་འདིའི་སྐོར་ལ་སྐྱོན་བརྗོད་དང་དྲི་བ། བསམ་འཆར་འདོན་རོགས།",
