      "support.feedbackEmailGeneral": "ཡི་གེ་འཕྲིན་སྐྱེལ། སྤྱིའི་བསམ་འཆར།",
      "support.feedbackEmailApp": "ཡི་གེ་འཕྲིན་སྐྱེལ། མཉེན་ཆས་སྐོར་གྱི་དྲི་བ།",
      "faq.title": "དྲི་བ-ལན",
      "faq.q1.q": "ཡིག་སྒྱུར་ཡོངས་རྫོགས་ཞུ་དག་བྱས་ཟིན་ནམ།",
      "faq.q1.a": "བྱས་མེད། ད་ལྟའི་ཡིག་སྒྱུར་ཕལ་ཆེ་བ་ AI ཡིས་བཟོས་པ་ཡིན་པས་མུ་མཐུད་དུ་ལེགས་བཅོས་བྱེད་བཞིན་ཡོད་ལ། ཚང་མ་མཉམ་དུ་ཞུ་དག་དང་ཐ་སྙད་གཅིག་གྱུར་བྱེད་པར་དགའ་བསུ་ཞུ།",
      "faq.q2.q": "ངས་བཟོ་བཅོས་བྱེད་པར་རོགས་རམ་བྱེད་ཆོག་གམ།",
      "faq.q2.a": "ཆོག ཐོ་འགོད་དང་ཐོ་འཇུག་བྱས་རྗེས། ཡིག་སྒྱུར་གྱི་དུམ་བུར་ཐེངས་གཉིས་བརྡབ་ན་རྩོམ་སྒྲིག་དང་ཞུ་དག་གི་བསམ་འཆར་སྤྲད་ཆོག（བཤེར་འབྲས་ཐོན་རྗེས་གཞི་གྲངས་ཀྱི་པར་གཞི་རྗེས་མའི་ནང་དུ་འཆར་རྒྱུ་ཡིན）",
      "faq.q3.q": "དྲ་བ་མེད་པའི་སྐབས་སུ་སྤྱོད་ཆོག་གམ།",
      "faq.q3.a": "ཆོག ནང་དོན་རྣམས་ས་གནས་ཀྱི་ SQLite གཞི་གྲངས་མཛོད་དུ་ཉར་ཡོད་པས་དྲ་བ་མེད་པའི་སྐབས་སུ་སྤྱོད་ཆོག་ལ། དྲ་བ་ཡོད་སྐབས་གསར་སྒྱུར་བྱེད་ཆོག",
      "faq.q4.q": "མཉེན་ཆས་ནང་གཞི་གྲངས་ཕབ་ལེན་མ་ཐུབ་ན་གང་བྱེད།",
      "faq.q4.a":
        "གོང་གསལ་གཞི་གྲངས་མཛོད་ཕབ་ལེན་གྱི་སྦྲེལ་ཐག་བརྒྱུད་ནས་གཞི་གྲངས་ཐུམ་སྒྲིལ་ཕབ་ལེན་བྱས་ཏེ་མཉེན་ཆས་ནང་འཇུག་བྱེད། གལ་ཏེ་ཉེར་སྤྱོད་ཚོང་ཁང་སྤྱོད་མི་ཐུབ་ཚེ། གོང་གསལ་སྦྲེལ་ཐག་ནས་ Android APK དང་ Linux སྒྲིག་ཆས་ལེན་ཆོག",
      "footer.tagline": "ཡིག་སྒྱུར་མང་པོ་བསྡུར་ནས་ཀློག་པ་དང་ཞུ་དག་བྱེད་པའི་པ་ལིའི་ཏི་པི་ཊ་ཀའི་མཉེན་ཆས།",
