      "features.title": "အဓိက လုပ်ဆောင်ချက်များ",
      "features.subtitle": "နက်နဲစွာ လေ့လာခြင်းနှင့် ရေရှည် ဖတ်ရှုခြင်းအတွက် အကောင်းဆုံး ပြင်ဆင်ထားသည်—လျင်မြန်သော လမ်းညွှန်မှု၊ ဘာသာပြန်များစွာ ယှဉ်တွဲဖတ်ရှုခြင်းနှင့် ချောမွေ့သော စိစစ်မှု လုပ်ငန်းစဉ်။",
      "features.parallel.title": "ဘာသာပြန်များစွာ ယှဉ်တွဲဖတ်ရှုခြင်း",
      "features.parallel.body": "ပါဠိမူရင်းနှင့် ဘာသာစကားမျိုးစုံ ဘာသာပြန်များကို စာပိုဒ်အလိုက် တစ်ပြိုင်နက် ပြသပေးပြီး ပြသလိုသော ဘာသာစကားများကို လွတ်လပ်စွာ ရွေးချယ်နိုင်သည်။",
      "features.search.title": "စာသားအပြည့် ရှာဖွေမှု",
      "features.search.body": "ပါဠိမူရင်း သို့မဟုတ် ဘာသာပြန်များကို လက်ရှိစာအုပ် သို့မဟုတ် စာအုပ်အားလုံးအတွင်း ရှာဖွေနိုင်ပြီး စาသားစုများကိုပါ ရှာဖွေနိုင်သည်။",
      "features.proofread.title": "ဘာသာပြန် တည်းဖြတ်ခြင်းနှင့် စိစစ်ခြင်း",
      "features.proofread.body": "စာပိုဒ် ဘာသာပြန်ကို နှစ်ချက်နှိပ်၍ တည်းဖြတ်နိုင်သည်—အကောင့်ဝင်ပြီးပါက စိစစ်ချက်များ ပေးပို့ကာ အတူတူ ပါဝင်ဆောင်ရွက်နိုင်သည်။",
      "features.nav.title": "လျင်မြန်သော လမ်းညွှန်မှုနှင့် ခုန်ကူးခြင်း",
      "features.nav.body": "တိပိဋက အပင် + စာအုပ်တွင်း အကြောင်းအရာ—စာပိုဒ်နံပါတ် သို့မဟုတ် စာမျက်နှာနံပါတ် စနစ်အမျိုးမျိုးဖြင့် ခုန်ကူးနိုင်မှုကို ပံ့ပိုးသည်။",
      "features.dict.title": "အဘိဓာန် လုပ်ငန်းစဉ်",
      "features.dict.body": "ပါဠိစကားလုံးကို နှိပ်၍ သို့မဟုတ် အဘိဓာန်တွင် ရိုက်ထည့်၍ ရှာနိုင်သည်။ မတိကျသော ကိုက်ညီမှုသည် သရရှည်/တို၊ ṭ/t၊ ḍ/d၊ ḷ/l နှင့် နှာသံအမှတ်များအတွက် ကူညီသည်။",
      "features.split.title": "တဘ်များစွာနှင့် မျက်နှาပြင်ခွဲမှု",
      "features.split.body": "စာအုပ်များစွာကို တစ်ပြိုင်နက် ဖွင့်နိုင်သည်—ကျယ်ပြန့်သော မျက်နှาပြင်တွင် ဘေးချင်းယှဉ်၍ မျက်နှาပြင်ခွဲ ဖတ်ရှုနိုင်ပြီး အထားအသိုကို အလိုအလျောက် မှတ်သားထားသည်။",
      "features.tts.title": "အလိုအလျောက် လှိမ့်ခြင်းနှင့် ဘာသာပြန် ဖတ်ကြားခြင်း",
      "features.tts.body": "ရှည်လျားသော စာသားများအတွက် အလိုအလျောက် လှိမ့်ပေးသည်—လက်ရှိ စာပိုဒ်ကို ဖတ်ကြားပေးနိုင်ပြီး မီဒီယာ ထိန်းချုပ်မှုကို ပံ့ပိုးသည်။",
      "features.script.title": "ပါဠိ အက္ခရာ အမျိုးမျိုး",
      "features.script.body": "ပါဠိကို အက္ခရာ အမျိုးမျိုး (Roman, Devanagari, Thai, Myanmar, Tibetan စသည်) ဖြင့် ပြသနိုင်သည်။",

