      "support.feedbackIntro":
        "အက်ပ် သို့မဟုတ် ဤဝက်ဘ်ဆိုက်အကြောင်း ချို့ယွင်းချက် အကြောင်းပြုခြင်း၊ မေးခွန်းမေးခြင်း သို့မဟုတ် အကြံပြုခြင်း။",
      "support.feedbackGithub": "GitHub တွင် အကြောင်းကြားရန်",
      "support.feedbackEmailGeneral": "အီးမေးလ် — အထွေထွေ တုံ့ပြန်မှု",
      "support.feedbackEmailApp": "အီးမေးလ် — အက်ပ် ဆိုင်ရာ မေးခွန်းများ",
      "faq.title": "မေးလေ့ရှိသောမေးခွန်းများ",
      "faq.q1.q": "ဘာသာပြန်များအားလုံးကို စိစစ်ပြီးပြီလား?",
      "faq.q1.a": "မပြီးသေးပါ။ လက်ရှိ ဘာသာပြန် အများစုမှာ AI ဖြင့် ပြုလုပ်ထားခြင်း ဖြစ်ပြီး အမြဲတမ်း တိုးတက်အောင် လုပ်ဆောင်နေသည်—လူအများ ပါဝင် စိစစ်ရန်နှင့် ဝေါဟာရ ညှိနှိုင်းရန် ဖိတ်ခေါ်ပါသည်။",
      "faq.q2.q": "ကျွန်ုပ် ပြင်ဆင်ချက်များ ပေးနိုင်ပါသလား?",
      "faq.q2.a": "ပေးနိုင်ပါသည်။ မှတ်ပုံတင်ပြီး အကောင့်ဝင်ပါ—စာပိုဒ် ဘာသာပြန်ကို နှစ်ချက်နှိပ်၍ တည်းဖြတ်ကာ စိစစ်ချက် ပေးပို့နိုင်သည် (စစ်ဆေးပြီးနောက် နောက်ထပ် ဒေတာဘေ့စ် ဗားရှင်းများတွင် ပါဝင်မည်)။",
      "faq.q3.q": "အော့ဖ်လိုင်း သုံးနိုင်ပါသလား?",
      "faq.q3.a": "သုံးနိုင်ပါသည်။ အကြောင်းအရာများကို ဒေသတွင်း SQLite ဒေတာဘေ့စ်တွင် သိမ်းဆည်းထားသည်—အော့ဖ်လိုင်း သုံးနိုင်ပြီး အင်တာနက် ရှိချိန်တွင် အပ်ဒိတ်များ ရယူနိုင်သည်။",
      "faq.q4.q": "အက်ပ်အတွင်း ဒေတာဘေ့စ် ဒေါင်းလုဒ် မအောင်မြင်ပါက?",
      "faq.q4.a":
        "အထက်ပါ ဒေတာဘေ့စ် ဒေါင်းလုဒ် လင့်မှတစ်ဆင့် ဒေတာဘေ့စ် ပက်ကေ့ချ်ကို ဒေါင်းလုဒ်လုပ်ပြီး အက်ပ်သို့ ထည့်သွင်းပါ။ အကယ်၍ အက်ပ်စတိုးကို အသုံးမပြုနိုင်ပါက၊ အထက်ပါ လင့်မှတစ်ဆင့် Android APK နှင့် Linux အင်စတောလာများကို ရယူနိုင်ပါသည်။",
      "footer.tagline": "ဘာသာပြန်များစွာဖြင့် ပါဠိတိပိဋက ဖတ်ရှုခြင်းနှင့် စိစစ်ခြင်း ကိရိယာ။",
