      "nav.screenshots": "ภาพหน้าจอ",
      "privacy.title": "คำชี้แจงด้านความเป็นส่วนตัว",
      "privacy.body":
        "ยกเว้นผู้ใช้ที่เข้าร่วมการตรวจทานซึ่งต้องลงทะเบียนด้วยอีเมลและตั้งชื่อผู้ใช้ แอปนี้ไม่เก็บรวบรวมข้อมูลส่วนบุคคลอื่นใด",
