      "screenshots.caption4": "タブと分割表示で、広い画面で本文を比較。",
      "screenshots.alt1": "OpenTipitaka：パーリと訳文の段落対照ビュー。",
      "screenshots.alt2": "OpenTipitaka：ナビゲーションツリー、目次、辞書エリア。",
