      "screenshots.alt4": "OpenTipitaka：二分割レイアウトと複数タブ。",
      "online.title": "Tipiṭaka Translation（オンライン）",
      "online.subtitle":
        "OpenTipitaka アプリとあわせて、ブラウザで本プロジェクトの内容を読む主な方法です。",
      "online.maintainer": "聖種長老 Ariyavaṃsa（パオ系）が保守しています。",
      "online.cta": "サイトを開く",

      "features.title": "主な機能",
      "features.subtitle": "深い学習と長期的な読書に最適化：迅速なナビゲーション、複数の訳文の並列表示、スムーズな校正ワークフロー。",
      "features.parallel.title": "多訳対照読書",
      "features.parallel.body": "パーリ語原文と複数の言語の訳文を段落ごとに同時に表示し、表示する言語の組み合わせを自由に選択できます。",
      "features.search.title": "全文検索",
      "features.search.body": "パーリ語原文と訳文の検索をサポート。現在の書籍または全蔵から範囲を選択でき、フレーズ検索も可能です。",
      "features.proofread.title": "訳文の編集と校正",
      "features.proofread.body": "段落の訳文をダブルクリックすると編集ウィンドウが表示されます。ログイン後は校正案を送信し、プロジェクトに貢献できます。",
      "features.nav.title": "迅速なナビゲーションとジャンプ",
      "features.nav.body": "三蔵ディレクトリツリー + 書籍内目次。段落番号や様々なページ番号システムによるジャンプをサポートします。",
      "features.dict.title": "辞書ワークフロー",
      "features.dict.body": "パーリ語をタップ、または辞書に入力して検索できます。あいまい一致で長短母音、ṭ/t、ḍ/d、ḷ/l、鼻音記号の違いにも対応します。",
      "features.split.title": "マルチタブと分割画面",
      "features.split.body": "複数の書籍を同時に開くことができます。ワイド画面では多段並列の分割表示が可能で、レイアウトは自動的に保存されます。",
      "features.tts.title": "自動スクロールと訳文読み上げ",
      "features.tts.body": "長文読書のための自動スクロールをサポート。現在の段落の訳文を読み上げることができ、メディアコントロールも可能です。",
      "features.script.title": "多彩なパーリ語表記",
      "features.script.body": "様々なパーリ語転写表示（ローマ字、デーヴァナーガリー、タイ文字、ビルマ文字、チベット文字など）をサポートします。",

      "download.title": "ダウンロード & データ",
