      "faq.title": "FAQ",
      "faq.q1.q": "번역이 완전히 교정되었습니까?",
      "faq.q1.a": "아직 완료되지 않았습니다. 현재 번역의 대부분은 AI에 의해 생성되었으며 지속적으로 개선되고 있습니다. 모든 분들이 함께 교정과 용어 통일에 참여해 주시기를 초대합니다.",
