      "faq.q2.a": "네. 가입 후 로그인하여 문단 번역을 더블 클릭해 편집하고 교정 제안을 제출할 수 있습니다(심사 후 다음 데이터베이스 버전에 반영됩니다).",
      "faq.q3.q": "오프라인 사용을 지원합니까?",
      "faq.q3.a": "네. 내용은 로컬 SQLite 데이터베이스에 저장됩니다. 오프라인으로 사용할 수 있으며 온라인 시 업데이트를 받을 수 있습니다.",
      "faq.q4.q": "앱에서 데이터베이스 다운로드가 실패하면요?",
      "faq.q4.a":
        "위의 데이터베이스 다운로드 링크를 통해 데이터 패키지를 직접 받아 앱으로 가져오세요. 앱 스토어를 사용할 수 없을 때는 위의 다운로드 링크에서 Android APK 및 Linux 설치 파일을 받으세요.",
      "footer.tagline": "다중 번역 대조를 지원하는 팔리 삼장 독서 및 교정 도구.",
