      "features.title": "मुख्य विशेषताएँ",
      "features.subtitle": "गहन अध्ययन और दीर्घकालिक पठन के लिए अनुकूलित: तेज़ नेविगेशन, बहु-अनुवाद समानांतर पठन, और सहज प्रूफरीडिंग प्रक्रिया।",
      "features.parallel.title": "बहु-अनुवाद समानांतर पठन",
      "features.parallel.body": "पालि मूल और कई भाषाओं के अनुवादों को अनुच्छेद-दर-अनुच्छेद एक साथ प्रदर्शित करें, और अपनी पसंद की भाषाओं का चयन करें।",
      "features.search.title": "पूर्ण-पाठ खोज",
      "features.search.body": "पालि मूल और अनुवादों में खोज का समर्थन। वर्तमान पुस्तक या संपूर्ण तिपिटक में खोजें, और वाक्यांश खोज का भी उपयोग करें।",
      "features.proofread.title": "अनुवाद संपादन और प्रूफरीडिंग",
      "features.proofread.body": "संपादन विंडो खोलने के लिए अनुवाद अनुच्छेद पर डबल-क्लिक करें। लॉगिन के बाद सुधार सुझाव भेजें और योगदान दें।",
      "features.nav.title": "तेज़ नेविगेशन और जंप",
      "features.nav.body": "तिपिटक श्रेणी वृक्ष + पुस्तक के भीतर की विषयसूची। अनुच्छेद संख्या और विभिन्न पृष्ठ संख्या प्रणालियों के माध्यम से जंप करें।",
      "features.dict.title": "शब्दकोश कार्यप्रवाह",
      "features.dict.body": "पालि शब्द पर टैप करें या शब्दकोश में टाइप करें। धुंधला मिलान दीर्घ/ह्रस्व स्वर, ṭ/t, ḍ/d, ḷ/l और अनुनासिक चिह्नों में मदद करता है।",
      "features.split.title": "मल्टी-टैब और स्प्लिट स्क्रीन",
      "features.split.body": "एक साथ कई पुस्तकें खोलें। चौड़ी स्क्रीन पर बहु-स्तंभ समानांतर स्प्लिट स्क्रीन का उपयोग करें, और लेआउट स्वचालित रूप से सहेजा जाता है।",
      "features.tts.title": "ऑटो-स्क्रॉल और अनुवाद वाचन",
      "features.tts.body": "लंबे पाठ के लिए ऑटो-स्क्रॉल। वर्तमान अनुच्छेद का अनुवाद सुनने के लिए वाचन सुविधा और मीडिया नियंत्रण का उपयोग करें।",
      "features.script.title": "विविध पालि लिपियाँ",
      "features.script.body": "विविध पालि लिपियों (रोमन, देवनागरी, थाई, म्यांमार, तिब्बती आदि) में प्रदर्शन का समर्थन।",

