      "faq.title": "FAQ",
      "faq.q1.q": "क्या अनुवाद पूरी तरह से प्रूफरीड किए गए हैं?",
      "faq.q1.a": "अभी नहीं। वर्तमान अनुवादों का बड़ा हिस्सा AI द्वारा निर्मित है और निरंतर सुधार के अधीन है। हम सभी को प्रूफरीडिंग और शब्दावली मानकीकरण में सहयोग के लिए आमंत्रित करते हैं।",
      "faq.q2.q": "क्या मैं सुधारों में योगदान दे सकता हूँ?",
      "faq.q2.a": "हाँ। पंजीकरण और लॉगिन के बाद, आप अनुच्छेद अनुवाद पर डबल-क्लिक करके उसे संपादित कर सकते हैं और प्रूफरीडिंग सुझाव भेज सकते (समीक्षा के बाद अगले डेटाबेस संस्करणों में शामिल किया जाएगा)।",
      "faq.q3.q": "क्या यह ऑफ़लाइन काम करता है?",
      "faq.q3.a": "हाँ। सामग्री स्थानीय SQLite डेटाबेस में संग्रहीत है। आप इसे ऑफ़라인 उपयोग कर सकते हैं और ऑनलाइन होने पर अपडेट प्राप्त कर सकते हैं।",
      "faq.q4.q": "ऐप में डेटाबेस डाउनलोड विफल हो तो?",
      "faq.q4.a":
        "उपरोक्त डेटाबेस डाउनलोड लिंक के माध्यम से डेटा पैकेज डाउनलोड करें और ऐप में आयात करें। यदि ऐप स्टोर का उपयोग नहीं कर सकते हैं, तो उपरोक्त डाउनलोड लिंक से Android APK और Linux इंस्टॉलर प्राप्त कर सकते हैं。",
      "footer.tagline": "बहु-अनुवाद पाली त्रिपिटक: पठन और प्रूफरीडिंग उपकरण।",
      "footer.copyright": "© 2026 Sunanda",
      "license.title": "लाइसेंस जानकारी",
      "license.body":
        "सामग्री लाइसेंस\nजब तक अन्यथा न कहा गया हो, परियोजना के स्वामित्व वाली या पुनः लाइसेंस देने योग्य मौलिक सामग्री—जिसमें अनुवाद, शब्दकोश परिभाषाएँ, टिप्पणियाँ, संशोधित पाठ और अन्य मौलिक रचनाएँ शामिल हैं—CC BY-NC-SA 4.0 के अंतर्गत उपलब्ध है। संक्षेप में, श्रेय देते हुए आप इसे गैर-व्यावसायिक उद्देश्यों के लिए कॉपी, साझा और रूपांतरित कर सकते हैं, और रूपांतरित कार्य भी इसी लाइसेंस के अंतर्गत साझा करने होंगे।\n\nतृतीय-पक्ष सामग्री\nतृतीय-पक्ष पालि मूलपाठ, शब्दकोश और अन्य डेटा उपर्युक्त लाइसेंस में शामिल नहीं हैं और उनके अधिकारधारकों की शर्तों के अधीन रहते हैं। उनका समावेश, प्रारूप परिवर्तन, अनुक्रमण या संकलन उनकी मूल कॉपीराइट अथवा लाइसेंस स्थिति नहीं बदलता। अलग सूचना होने पर वही लागू होगी।\n\nसॉफ़्टवेयर कोड\nOpenTipitaka App का कोड उपर्युक्त Creative Commons लाइसेंस के अंतर्गत नहीं है। स्पष्ट रूप से अन्यथा बताए जाने तक सभी अधिकार सुरक्षित हैं।",
