      "features.title": "Funciones principales",
      "features.subtitle": "Optimizado para el estudio profundo y la lectura prolongada: navegación rápida, visualización paralela de múltiples traducciones y un flujo de revisión fluido.",
      "features.parallel.title": "Lectura paralela multilingüe",
      "features.parallel.body": "Muestra el original en pali y múltiples traducciones por párrafo simultáneamente, con libertad para elegir los idiomas a mostrar.",
      "features.search.title": "Búsqueda de texto completo",
      "features.search.body": "Soporta búsqueda en el original pali y en las traducciones. Puede elegir el libro actual o toda la colección, incluyendo búsqueda de frases.",
      "features.proofread.title": "Edición y revisión de traducciones",
      "features.proofread.body": "Doble clic en un párrafo traducido para editarlo en una ventana emergente. Tras iniciar sesión, puede enviar sugerencias de revisión para colaborar.",
      "features.nav.title": "Navegación y saltos rápidos",
      "features.nav.body": "Árbol del Tipitaka + índice interno del libro. Permite saltar por número de párrafo y diversos sistemas de numeración de páginas.",
      "features.dict.title": "Flujo de trabajo con diccionarios",
      "features.dict.body": "Toque una palabra pali o escríbala en el diccionario. La coincidencia aproximada ayuda con vocales largas/cortas, ṭ/t, ḍ/d, ḷ/l y marcas nasales.",
      "features.split.title": "Múltiples pestañas y pantalla dividida",
      "features.split.body": "Abra varios libros a la vez. En pantallas anchas permite división en varias columnas paralelas; el diseño se guarda automáticamente.",
      "features.tts.title": "Desplazamiento automático y lectura de voz",
      "features.tts.body": "Soporta desplazamiento automático para lecturas largas. Puede leer en voz alta el párrafo actual y admite controles multimedia.",
      "features.script.title": "Diversos alfabetos pali",
      "features.script.body": "Soporta visualización en múltiples alfabetos (romano, devanagari, tailandés, birmano, tibetano, etc.).",

