      "faq.title": "FAQ",
      "faq.q1.q": "¿Están las traducciones totalmente revisadas?",
      "faq.q1.a": "Aún no. La gran mayoría de las traducciones actuales han sido generadas por IA y están en mejora continua; invitamos a todos a participar en la revisión y unificación de términos.",
      "faq.q2.q": "¿Puedo contribuir con correcciones?",
      "faq.q2.a": "Sí. Tras registrarse e iniciar sesión, puede hacer doble clic en una traducción para editarla y enviar sugerencias de revisión (que se publicarán en futuras versiones tras ser revisadas).",
      "faq.q3.q": "¿Funciona sin conexión?",
      "faq.q3.a": "Sí. El contenido se almacena en bases de datos SQLite locales; se puede usar sin conexión y recibir actualizaciones al conectarse.",
      "faq.q4.q": "¿Qué hago si falla la descarga de la base de datos en la app?",
      "faq.q4.a":
        "Use el enlace de descarga de bases de datos de arriba para obtener el paquete e importarlo manualmente. Si no puede usar las tiendas, obtenga los instaladores Android APK o de Linux mediante los enlaces de descarga indicados.",
      "footer.tagline": "Herramienta de lectura y revisión del Tipitaka Pali con múltiples traducciones.",
      "footer.copyright": "© 2026 Sunanda.",
      "license.title": "Información de licencias",
      "license.body":
        "Licencia del contenido\nSalvo indicación en contrario, el contenido original cuyos derechos pertenecen al proyecto o que este puede volver a licenciar —incluidas traducciones, definiciones de diccionario, anotaciones, textos revisados y otras obras originales— se ofrece bajo CC BY-NC-SA 4.0. En resumen, permite copiar, compartir y adaptar con atribución para fines no comerciales, y las obras derivadas deben compartirse bajo la misma licencia.\n\nMateriales de terceros\nLos textos pali, diccionarios y demás datos de terceros no están cubiertos por la licencia anterior y siguen sujetos a las licencias o autorizaciones de sus titulares. Su inclusión, conversión de formato, indexación o compilación no modifica su situación jurídica. Si existe un aviso específico, prevalece dicho aviso.\n\nCódigo del software\nEl código de OpenTipitaka App no está cubierto por la licencia Creative Commons anterior. Salvo indicación expresa, todos los derechos quedan reservados.",
