      "features.subtitle": "Dioptimalkan untuk studi mendalam dan pembacaan jangka panjang: navigasi cepat, perbandingan multi-terjemahan, dan alur kerja koreksi yang mulus.",
      "features.parallel.title": "Baca Paralel Multi-terjemahan",
      "features.parallel.body": "Menampilkan teks asli Pali dan terjemahan multi-bahasa secara bersamaan per paragraf, dengan kebebasan memilih kombinasi bahasa yang ingin ditampilkan.",
