      "faq.title": "FAQ",
      "faq.q1.q": "Apakah terjemahan sudah dikoreksi sepenuhnya?",
      "faq.q1.a": "Belum. Sebagian besar terjemahan saat ini dihasilkan oleh AI dan terus ditingkatkan; kami mengundang semua orang untuk berpartisipasi dalam koreksi dan penyelarasan istilah.",
      "faq.q2.q": "Bisakah saya berkontribusi memberikan revisi?",
      "faq.q2.a": "Bisa. Setelah mendaftar dan masuk, Anda dapat mengeklik dua kali pada paragraf terjemahan untuk mengedit dan mengirimkan saran koreksi (akan diterbitkan pada versi database berikutnya setelah ditinjau).",
      "faq.q3.q": "Apakah mendukung penggunaan offline?",
      "faq.q3.a": "Ya. Konten disimpan dalam database SQLite lokal; dapat digunakan secara offline dan menerima pembaruan saat terhubung ke internet.",
      "faq.q4.q": "Bagaimana jika unduhan basis data di aplikasi gagal?",
      "faq.q4.a":
        "Gunakan tautan unduhan database di atas untuk mendapatkan paket data dan mengimpornya ke aplikasi. Jika tidak dapat menggunakan toko aplikasi, dapatkan APK Android atau pemasang Linux melalui tautan unduhan yang disediakan.",
      "footer.tagline": "Alat baca dan koreksi Tipitaka Pali dengan multi-terjemahan.",
