      "features.title": "Fonctionnalités principales",
      "features.subtitle": "Optimisé pour l’étude approfondie et la lecture de longue durée : navigation rapide, affichage parallèle de plusieurs traductions et flux de relecture fluide.",
      "features.parallel.title": "Lecture parallèle multi-traductions",
      "features.parallel.body": "Affiche simultanément l’original en pali et plusieurs traductions par paragraphe, avec la liberté de choisir les langues à afficher.",
      "features.search.title": "Recherche plein texte",
      "features.search.body": "Prend en charge la recherche dans l’original pali et les traductions. Vous pouvez choisir le livre actuel ou l’ensemble du Tipitaka, y compris la recherche de phrases.",
      "features.proofread.title": "Édition et relecture des traductions",
      "features.proofread.body": "Double-cliquez sur un paragraphe traduit pour l’éditer via une fenêtre contextuelle. Une fois connecté, vous pouvez soumettre des suggestions de relecture pour contribuer au projet.",
      "features.nav.title": "Navigation et sauts rapides",
      "features.nav.body": "Arbre des catégories du Tipitaka + table des matières interne au livre. Permet de sauter par numéro de paragraphe et divers systèmes de numérotation de pages.",
      "features.dict.title": "Flux de travail avec dictionnaires",
      "features.dict.body": "Touchez un mot pāli ou saisissez-le dans le dictionnaire. La correspondance approximative aide avec les voyelles longues/courtes, ṭ/t, ḍ/d, ḷ/l et les marques nasales.",
      "features.split.title": "Multi-onglets et écran partagé",
      "features.split.body": "Ouvrez plusieurs livres à la fois. Sur les écrans larges, profitez de la division en plusieurs colonnes parallèles ; la mise en page est enregistrée automatiquement.",
      "features.tts.title": "Défilement automatique et lecture vocale",
      "features.tts.body": "Prend en charge le défilement automatique pour les lectures de longs textes. Peut lire à haute voix la traduction du paragraphe actuel et prend en charge les commandes multimédias.",
      "features.script.title": "Divers alphabets palis",
      "features.script.body": "Prend en charge l’affichage du pali dans plusieurs écritures de translittération (romain, devanagari, thaï, birman, tibétain, etc.).",

