      "faq.title": "FAQ",
      "faq.q1.q": "Les traductions sont-elles entièrement relues ?",
      "faq.q1.a": "Pas encore. La grande majorité des traductions actuelles ont été générées par IA et sont en amélioration continue ; nous invitons tout le monde à participer à la relecture et à l’harmonisation des termes.",
      "faq.q2.q": "Puis-je contribuer aux corrections ?",
      "faq.q2.a": "Oui. Après vous être inscrit et connecté, vous pouvez double-cliquer sur un paragraphe de traduction pour l’éditer et soumettre des suggestions de relecture (qui seront publiées dans les versions futures de la base de données après examen).",
      "faq.q3.q": "L’application fonctionne-t-elle hors ligne ?",
      "faq.q3.a": "Oui. Le contenu est stocké dans des bases de données SQLite locales ; il peut être utilisé hors ligne et mis à jour lors de la connexion à Internet.",
      "faq.q4.q": "Que faire si le téléchargement de la base de données échoue dans l’app ?",
      "faq.q4.a":
        "Utilisez le lien de téléchargement de base de données ci-dessus pour obtenir le paquet et l’importer manuellement. Si vous ne pouvez pas utiliser les stores, procurez-vous l’APK Android ou les installateurs Linux via les liens de téléchargement indiqués.",
