      "features.title": "Hauptfunktionen",
      "features.subtitle": "Optimiert für vertieftes Studium und langfristiges Lesen: Schnelle Navigation, mehrsprachige Parallelanzeige und ein reibungsloser Korrektur-Workflow.",
      "features.parallel.title": "Mehrsprachige Parallellektüre",
      "features.parallel.body": "Pali-Original und mehrere Übersetzungen absatzweise gleichzeitig anzeigen. Wählen Sie frei, welche Sprachen kombiniert werden sollen.",
      "features.search.title": "Volltextsuche",
      "features.search.body": "Unterstützt die Suche im Pali-Original und in den Übersetzungen. Wählen Sie zwischen dem aktuellen Buch oder der gesamten Sammlung, inklusive Phrasensuche.",
      "features.proofread.title": "Übersetzung bearbeiten & korrigieren",
      "features.proofread.body": "Doppelklick auf einen Übersetzungsabsatz öffnet das Bearbeitungsfenster. Melden Sie sich an, um Korrekturvorschläge einzureichen und mitzuwirken.",
      "features.nav.title": "Schnelle Navigation & Sprung",
      "features.nav.body": "Tipitaka-Strukturbaum + Inhaltsverzeichnis im Buch. Springen Sie nach Absatznummer oder verschiedenen Seitennummerierungssystemen.",
      "features.dict.title": "Wörterbuch-Workflow",
      "features.dict.body": "Tippen Sie ein Pali-Wort an oder geben Sie es im Wörterbuch ein. Unscharfe Suche hilft bei langen/kurzen Vokalen, ṭ/t, ḍ/d, ḷ/l und Nasalzeichen.",
      "features.split.title": "Multi-Tabs & geteilter Bildschirm",
      "features.split.body": "Mehrere Bücher gleichzeitig öffnen. Auf breiten Bildschirmen wird die mehrspaltige Parallelansicht unterstützt; das Layout wird automatisch gespeichert.",
      "features.tts.title": "Auto-Scroll & Vorlesefunktion",
      "features.tts.body": "Unterstützt automatisches Scrollen für langes Lesen. Kann den aktuellen Übersetzungsabsatz vorlesen und bietet Mediensteuerung.",
      "features.script.title": "Diverse Pali-Schriften",
      "features.script.body": "Unterstützt die Anzeige von Pali in verschiedenen Schriften (Latein/Roman, Devanagari, Thai, Myanmar, Tibetisch usw.).",

