        "සාක්ෂරකරණයට සහභාගී වන පරිශීලකයින් ඊමේල් ලිපිනයකින් ලියාපදිංචි වී පරිශීලක නාමයක් ඇතුළත් කළ යුතු ය; එයින් ඔබ්බෙන් මෙම යෙදුම වෙනත් පෞද්ගලික තොරතුරු එකතු නොකරයි.",
