      "screenshots.caption2": "ත්‍රිපිටක වෘක්ෂය, පොත් අන්තර්ගතය සහ ශබ්ද කෝෂය.",
      "screenshots.caption3": "පාලි සහ පරිවර්තන තුළ පුරා ලේඛන සෙවීම.",
      "screenshots.caption4": "පුළුල් තිරවල පෙළ සංසන්දනයට ටැබ් සහ තිර බෙදීම.",
      "screenshots.alt1": "OpenTipitaka: ඡේද අනුව පාලි සහ පරිවර්තන තීරු.",
      "screenshots.alt2": "OpenTipitaka: සංචාරණ වෘක්ෂය, අන්තර්ගතය සහ ශබ්ද කෝෂ තීරුව.",
      "screenshots.alt3": "OpenTipitaka: සෙවුම් ක්ෂේත්‍රය සහ ප්‍රතිඵල ලැයිස්තුව.",
      "screenshots.alt4": "OpenTipitaka: ද්වි තීරු බෙදීම සහ බහු ටැබ්.",
      "mock.title": "කියවන්නා",
      "mock.leftPanel": "ත්‍රිපිටකය · අන්තර්ගතය · ශබ්ද කෝෂය",
