      "mock.paliLabel": "පාලි (රෝමානු / දේවනාගරී / තායි …)",
      "mock.translationLabel": "පරිවර්තනය (චීන / ඉංග්‍රීසි …)",
      "mock.tools.search": "සොයන්න",
