      "trust.stackTitle": "Flutter සමඟ නිර්මාණය",
      "trust.stackValue": "macOS · Windows · Linux · iOS · Android",
      "trust.dataTitle": "දත්ත",
      "trust.dataValue": "SQLite දත්ත සමුදායන්, ආයාතය සහ යාවත්කාල",
      "features.title": "ප්‍රධාන විශේෂාංග",
      "features.subtitle": "ගැඹුරු අධ්‍යයනය සහ දිගුකාලීන කියවීම සඳහා ප්‍රශස්ත කර ඇත: වේගවත් සංචාරණය, බහු-පරිවර්තන සංසන්දනය සහ සුමට සංශෝධන ක්‍රියාවලිය.",
      "features.parallel.title": "බහු-පරිවර්තන සමාන්තර කියවීම",
      "features.parallel.body": "ඡේද අනුව පාලි මූලාශ්‍රය සහ බහු භාෂා පරිවර්තන එකවර ප්‍රදර්ශනය කරයි. සංසන්දනය කිරීමට අවශ්‍ය භාෂා සංයෝජනය නිදහසේ තෝරා ගන්න.",
      "features.search.title": "සම්පූර්ණ පෙළ සෙවීම",
      "features.search.body": "පාලි මූලාශ්‍රය සහ පරිවර්තන සෙවීමට සහාය දක්වයි. වත්මන් පොත හෝ මුළු එකතුව තෝරාගත හැක, වාක්‍ය ඛණ්ඩ සෙවීම ඇතුළුව.",
      "features.proofread.title": "පරිවර්තන සංස්කරණය සහ සංශෝධනය",
      "features.proofread.body": "සංස්කරණය කිරීමට පරිවර්තන ඡේදයක් මත දෙවරක් ක්ලික් කරන්න. ලොග් වූ පසු ඔබට සංශෝධන යෝජනා ඉදිරිපත් කළ හැක.",
      "features.nav.title": "වේගවත් සංචාරණය සහ පැනීම",
      "features.nav.body": "ත්‍රිපිටක ව්‍යුහ ව්‍යුහය + පොත තුළ පටුන. ඡේද අංකය හෝ විවිධ පිටු අංකන පද්ධති අනුව පැනීමට සහාය දක්වයි.",
      "features.dict.title": "ශබ්දකෝෂ කාර්ය ප්‍රවාහය",
      "features.dict.body": "පාලි වචනයක් තට්ටු කරන්න හෝ ශබ්දකෝෂයේ ටයිප් කරන්න. අනුමාන ගැළපීම දිගු/කෙටි ස්වර, ṭ/t, ḍ/d, ḷ/l හා නාසික ලකුණු වෙනස්කම් සඳහා උපකාරී වේ.",
      "features.split.title": "බහු-ටැබ් සහ තිරය බෙදීම",
      "features.split.body": "එකවර පොත් කිහිපයක් විවෘත කළ හැක. පුළුල් තිරවල තීරු කිහිපයකින් බෙදා පෙන්වීමට සහාය දක්වන අතර පිරිසැලසුම ස්වයංක්‍රීයව සුරැකේ.",
      "features.tts.title": "ස්වයංක්‍රීය අනුචලනය සහ ශබ්ද නගා කියවීම",
      "features.tts.body": "දිගු පෙළ කියවීම සඳහා ස්වයංක්‍රීය අනුචලනයට සහාය දක්වයි. වත්මන් පරිවර්තන ඡේදය ශබ්ද නගා කියවිය හැකි අතර මාධ්‍ය පාලනයට සහාය වේ.",
      "features.script.title": "පාලි විවිධ අක්ෂර",
      "features.script.body": "පාලි භාෂාව විවිධ අක්ෂරවලින් (ලතින්/රෝම, දේවනාගරී, තායි, මියන්මාර්, ටිබෙට් ආදිය) ප්‍රදර්ශනය කිරීමට සහාය දක්වයි.",
      "online.title": "Tipiṭaka Translation (අන්තර්ජාලය)",
      "online.subtitle":
        "බ්‍රව්සරයෙන් මෙම ව්‍යාපෘතියේ අන්තර්ගතය කියවන ප්‍රධාන මාර්ගය, OpenTipitaka යෙදුම සමඟ.",
      "online.maintainer": "ගරු අරියවංශ හිමි (පාඕක්) විසින් නඩත්තු කරයි.",
      "online.cta": "වෙබ් අඩවිය විවෘත කරන්න",
      "download.title": "බාගැනීම සහ දත්ත",
      "download.quickStart.title": "වේගවත් ආරම්භය",
      "download.quickStart.s1":
        "App Store (iPhone, iPad, Mac) හෝ Google Play (Android) මඟින් ස්ථාපනය කරන්න. Windows සහ Linux සඳහා Pa-Auk ගොනු සේවාදායකයේ Tipitaka ෆෝල්ඩරයෙන් ස්ථාපකය බාගන්න (ඊළඟ කාඩ්පතේ සබැඳිය).",
      "download.quickStart.s2": "පළමු වරට විවෘත කිරීමේදී යෙදුමේ භාෂාව තෝරන්න.",
      "download.quickStart.s3": "අන්තර්ජාලය සමඟ සිටින විට යෙදුම තුළ පරිවර්තන දත්ත සමුදායන් බාගන්න.",
      "download.dataHelp.title":
        "Android/Linux ස්ථාපක, පරිවර්තන දත්ත සමුදායන්, EPUB/PDF/TXT ලේඛන බාගැනීම",
      "download.dataHelp.documentsCta": "EPUB, PDF සහ TXT ලේඛන බාගැනීම",
      "download.dataHelp.apkIntro":
        "Android APK සහ Windows හා Linux ස්ථාපක Pa-Auk සමාජ ගොනු අඩවියේ ප්‍රකාශයට පත් කර ඇත (යට සබැඳිය). යෙදුම් වෙළඳසැලකින් ස්ථාපනය කළ නොහැකි නම් එම සබැඳිය භාවිතා කරන්න.",
      "download.dataHelp.apkCta": "Android APK · Windows · Linux ස්ථාපක බාගැනීම",
      "download.dataHelp.manualIntro":
        "යෙදුම තුළ දත්ත සමුදාය බාගැනීම අසාර්ථක නම්, පරිවර්තන දත්ත පැකේජය යට සබැඳියෙන් අතින් බාගෙන යෙදුමට ආයාත කරන්න.",
      "download.dataHelp.manualCta": "පරිවර්තන දත්ත සමුදාය බාගැනීම",
