      "hero.kicker": "Tipitaka em pali · Múltiplas traduções · Revisão",
      "hero.title": "Leia, compare, pesquise e revise o Tipitaka em pali com conforto em qualquer dispositivo.",
      "hero.mission":
        "Sob a orientação do Venerável Kumārābhivaṃsa Sayadaw, este projeto dedica-se a transmitir a sabedoria antiga por meio da tecnologia moderna. Ao aproximar as escrituras em pali das necessidades multilíngues contemporâneas, usamos tradução assistida por IA e o aplicativo multiplataforma OpenTipitaka para construir uma plataforma confiável de tradução multilíngue e leitura paralela. Nossa missão é tornar a profunda sabedoria do Theravāda Tipiṭaka, Aṭṭhakathā e Ṭīkā acessível a todos os praticantes e estudiosos.\n\nOpenTipitaka é desenvolvido pelo Venerável Sunanda e operado pela Dhamma Sarana LLC. É um aplicativo multilíngue de leitura e revisão do Tipitaka em pali, com experiência completa em Windows, macOS, iOS, Android e Linux. O OpenTipitaka oferece leitura paralela por parágrafo do texto em pali e das traduções, com dicionários profissionais integrados e busca em texto completo, além de integrar profundamente gerenciamento de marcadores, comparação em tela dividida, alternância entre abas, rolagem automática e leitura em voz alta (TTS) das traduções. Convidamos leitores de todo o mundo a participar da revisão e ajudar a refinar este tesouro de sabedoria no caminho da libertação.",
      "hero.translationLangs":
        "As línguas de tradução atualmente suportadas incluem chinês, inglês, vietnamita, tailandês, hindi, indonésio, japonês, coreano, espanhol, francês, alemão, birmanês, cingalês, marata, khmer, bengali e tibetano. Mais línguas serão adicionadas ao longo do tempo.",
      "hero.translationQualityNote":
        "Durante a tradução por IA, a grande maioria dos suttas, a maior parte dos comentários e alguns subcomentários foram traduzidos com referência a explicações palavra por palavra em birmanês (Nissaya) e traduções birmanesas. No geral, as traduções estão se aproximando da qualidade de tradução humana e têm alto valor de referência. Ainda há espaço para melhorar a precisão, a consistência terminológica e aspectos relacionados; continuaremos aprimorando e atualizando periodicamente.",

