      "hero.kicker": "ព្រះត្រៃបិដកភាសាបាលី · ការបកប្រែច្រើនភាសា · ការពិនិត្យកែសម្រួល",
      "hero.title": "អាន ប្រៀបធៀប ស្វែងរក និងពិនិត្យកែសម្រួលព្រះត្រៃបិដកភាសាបាលីបានយ៉ាងស្រួលលើឧបករណ៍ណាក៏បាន។",
      "hero.mission":
        "ក្រោមការណែនាំរបស់ព្រះតេជព្រះគុណ Kumārābhivaṃsa Sayadaw គម្រោងនេះឧទ្ទិសដល់ការនាំប្រាជ្ញាបុរាណឱ្យបន្តទៅមុខតាមរយៈបច្ចេកវិទ្យាទំនើប។ ដោយភ្ជាប់ចន្លោះរវាងគម្ពីរភាសាបាលី និងតម្រូវការច្រើនភាសាសម័យថ្មី យើងប្រើការបកប្រែជំនួយដោយ AI និងកម្មវិធីឆ្លងវេទិកា OpenTipitaka ដើម្បីកសាងវេទិកាដែលអាចទុកចិត្តបានសម្រាប់ការបកប្រែច្រើនភាសា និងការអានប្រៀបធៀប។ បេសកកម្មរបស់យើងគឺធ្វើឱ្យប្រាជ្ញាដ៏ជ្រាលជ្រៅនៃ Theravāda Tipiṭaka, Aṭṭhakathā និង Ṭīkā អាចចូលដល់ដៃអ្នកប្រតិបត្តិ និងអ្នកសិក្សាទាំងអស់។\n\nOpenTipitaka ត្រូវបានអភិវឌ្ឍដោយព្រះតេជព្រះគុណ Sunanda និងដំណើរការដោយ Dhamma Sarana LLC។ វាជាកម្មវិធីអាន និងពិនិត្យកែសម្រួលព្រះត្រៃបិដកភាសាបាលីច្រើនភាសា ដែលផ្ដល់បទពិសោធន៍ពេញលេញលើ Windows, macOS, iOS, Android និង Linux។ OpenTipitaka គាំទ្រការអានបាលីដើម និងការបកប្រែជាប្រយោគតាមកថាខណ្ឌ មានវចនានុក្រមជំនាញភ្ជាប់មកជាមួយ និងការស្វែងរកពេញអត្ថបទ ហើយរួមបញ្ចូលយ៉ាងជ្រាលជ្រៅនូវការគ្រប់គ្រងចំណាំ ការប្រៀបធៀបអេក្រង់បំបែក ការផ្លាស់ប្ដូរផ្ទាំងជាច្រើន ការរំកិលស្វ័យប្រវត្តិ និងការអានជាសំឡេង (TTS) សម្រាប់ការបកប្រែ។ យើងអញ្ជើញអ្នកអានទូទាំងពិភពលោកចូលរួមពិនិត្យកែសម្រួល និងជួយធ្វើឱ្យឃ្លាំងប្រាជ្ញានេះកាន់តែល្អប្រសើរឡើងលើមាគ៌ាទៅកាន់វិមុត្តិ។",
      "hero.translationLangs":
        "ភាសាបកប្រែដែលគាំទ្របច្ចុប្បន្នរួមមាន ចិន អង់គ្លេស វៀតណាម ថៃ ហិណ្ឌី ឥណ្ឌូនេស៊ី ជប៉ុន កូរ៉េ អេស្ប៉ាញ បារាំង អាល្លឺម៉ង់ ភូមា ស៊ីនហាឡា ម៉ារ៉ាធី ខ្មែរ បង់ក្លា និងទីបេ។ ភាសាបន្ថែមនឹងត្រូវបានបន្ថែមនៅពេលក្រោយ។",
      "hero.translationQualityNote":
        "ក្នុងដំណើរការបកប្រែដោយ AI សុត្តភាគច្រើនបំផុត អត្ថកថាភាគច្រើន និងអនុអត្ថកថាមួយចំនួន ត្រូវបានបកប្រែដោយយោងតាមការពន្យល់ពាក្យមួយៗជាភាសាភូមា (Nissaya) និងការបកប្រែភាសាភូមា។ ជារួម ការបកប្រែកំពុងខិតជិតគុណភាពការបកប្រែដោយមនុស្ស និងមានតម្លៃយោងខ្ពស់។ នៅតែមានកន្លែងសម្រាប់កែលម្អភាពត្រឹមត្រូវ ភាពស្របគ្នានៃពាក្យបច្ចេកទេស និងផ្នែកពាក់ព័ន្ធផ្សេងៗ; យើងនឹងបន្តកែលម្អ និងធ្វើបច្ចុប្បន្នភាពជាបន្តបន្ទាប់។",

