      "hero.kicker": "ພຣະໄຕປິດົກພາສາປາລີ · ຄຳແປຫຼາຍພາສາ · ການກວດແກ້",
      "hero.title": "ອ່ານ, ປຽບທຽບ, ຄົ້ນຫາ ແລະ ຮ່ວມກວດແກ້ພຣະໄຕປິດົກພາສາປາລີໄດ້ຢ່າງສະດວກໃນທຸກອຸປະກອນ.",
      "hero.mission":
        "ພາຍໃຕ້ການຊີ້ນຳຂອງພຣະອາຈານ Kumārābhivaṃsa Sayadaw, ໂຄງການນີ້ອຸທິດໃຫ້ກັບການນຳພາປັນຍາໂບຮານໃຫ້ສືບຕໍ່ຜ່ານເທັກໂນໂລຢີສະໄໝໃໝ່. ໂດຍການເຊື່ອມຊ່ອງຫວ່າງລະຫວ່າງຄຳພີພາສາປາລີ ແລະ ຄວາມຕ້ອງການຫຼາຍພາສາໃນປັດຈຸບັນ, ພວກເຮົາໃຊ້ການແປທີ່ຊ່ວຍໂດຍ AI ແລະ ແອັບ OpenTipitaka ທີ່ໃຊ້ໄດ້ຫຼາຍແພລດຟອມ ເພື່ອສ້າງແພລດຟອມທີ່ເຊື່ອຖືໄດ້ສຳລັບການແປຫຼາຍພາສາ ແລະ ການອ່ານຄຽງຂ້າງ. ພາລະກິດຂອງພວກເຮົາແມ່ນການນຳປັນຍາອັນເລິກຊຶ້ງຂອງ Theravāda Tipiṭaka, Aṭṭhakathā ແລະ Ṭīkā ໃຫ້ຢູ່ໃນມືຂອງຜູ້ປະຕິບັດ ແລະ ນັກສຶກສາທຸກຄົນ.\n\nOpenTipitaka ພັດທະນາໂດຍພຣະ Sunanda ແລະ ດຳເນີນງານໂດຍ Dhamma Sarana LLC. ນີ້ແມ່ນແອັບອ່ານ ແລະ ກວດແກ້ພຣະໄຕປິດົກພາສາປາລີແບບຫຼາຍພາສາ ທີ່ໃຫ້ປະສົບການຄົບຖ້ວນໃນ Windows, macOS, iOS, Android ແລະ Linux. OpenTipitaka ຮອງຮັບການອ່ານຕົ້ນສະບັບປາລີ ແລະ ຄຳແປຄຽງຂ້າງຕາມຫຍໍ້ໜ້າ, ມີພະຈະນານຸກົມມືອາຊີບໃນຕົວ ແລະ ການຄົ້ນຫາເຕັມຂໍ້ຄວາມ, ພ້ອມກັບການຈັດການບຸກມາກ, ການປຽບທຽບແບບແບ່ງໜ້າຈໍ, ການສະຫຼັບແທັບຫຼາຍອັນ, ການເລື່ອນອັດຕະໂນມັດ ແລະ ການອ່ານຄຳແປອອກສຽງ (TTS). ພວກເຮົາເຊີນຊວນຜູ້ອ່ານທົ່ວໂລກໃຫ້ຮ່ວມກວດແກ້ ແລະ ຊ່ວຍປັບປຸງຄັງປັນຍານີ້ໃຫ້ດີຍິ່ງຂຶ້ນໃນເສັ້ນທາງສູ່ວິມຸດຕິ.",
      "hero.translationLangs":
        "ພາສາຄຳແປທີ່ຮອງຮັບໃນປັດຈຸບັນປະກອບມີ ຈີນ, ອັງກິດ, ຫວຽດນາມ, ໄທ, ຮິນດີ, ອິນໂດເນເຊຍ, ຍີ່ປຸ່ນ, ເກົາຫຼີ, ສະເປນ, ຝຣັ່ງ, ເຢຍລະມັນ, ມຽນມາ, ສິງຫລະ, ມາຣາທີ, ຂະແມ, ເບັງກາລີ ແລະ ທິເບດ. ຈະມີການເພີ່ມພາສາອື່ນໆ ໃນອະນາຄົດ.",
      "hero.translationQualityNote":
        "ໃນຂະບວນການແປດ້ວຍ AI, ສຸດຕະສ່ວນໃຫຍ່, ອັດຖະກະຖາສ່ວນໃຫຍ່ ແລະ ອະນຸອັດຖະກະຖາບາງສ່ວນໄດ້ແປໂດຍອ້າງອີງຄຳອະທິບາຍພາສາມຽນມາແບບຄຳຕໍ່ຄຳ (Nissaya) ແລະ ຄຳແປພາສາມຽນມາ. ໂດຍລວມແລ້ວ ຄຳແປໃກ້ຄຽງຄຸນນະພາບການແປຂອງມະນຸດ ແລະ ມີຄຸນຄ່າອ້າງອີງສູງ. ຍັງມີພື້ນທີ່ໃຫ້ປັບປຸງດ້ານຄວາມຖືກຕ້ອງ, ຄວາມສອດຄ່ອງຂອງຄຳສັບ ແລະ ດ້ານອື່ນໆ; ພວກເຮົາຈະປັບປຸງຕໍ່ໄປ ແລະ ອັບເດດເປັນໄລຍະ.",

