      "features.search.body": "ຄົ້ນຫາປາລີ ຫຼື ຄຳແປໃນປື້ມປັດຈຸບັນ ຫຼື ທຸກປື້ມ, ພ້ອມຮອງຮັບການຄົ້ນຫາແບບວະລີ.",
      "features.proofread.title": "ການກວດແກ້ ແລະ ແກ້ໄຂ",
      "features.proofread.body": "ດັບເບິນຄລິກເພື່ອແກ້ໄຂຫຍໍ້ໜ້າຄຳແປ. ເຂົ້າລະບົບເພື່ອສົ່ງການຮ່ວມກວດແກ້.",
      "features.nav.title": "ນຳທາງໄວ",
      "features.nav.body": "ໂຄງຕົ້ນໄມ້ Tipitaka + ເນື້ອໃນໃນປື້ມ. ຂ້າມໄປຕາມຫຍໍ້ໜ້າ ຫຼື ລະບົບເລກໜ້າຫຼາຍແບບ.",
      "features.dict.title": "ການໃຊ້ພະຈະນານຸກົມ",
      "features.dict.body": "ແຕະຄຳປາລີ ຫຼື ພິມຄຳໃນພະຈະນານຸກົມ. ການຈັບຄູ່ແບບປະມານຊ່ວຍກັບສະຫຼະຍາວ/ສັ້ນ, ṭ/t, ḍ/d, ḷ/l ແລະ ເຄື່ອງໝາຍນາສິກ.",
      "features.split.title": "ແບ່ງໜ້າຈໍ ແລະ ແທັບ",
      "features.split.body": "ເປີດປື້ມຫຼາຍຫົວໃນແທັບ ແລະ ສະແດງຄຽງຂ້າງໃນຈໍກວ້າງ. ໂຄງຮ່າງຂອງທ່ານຈະຖືກຈື່ໄວ້.",
      "features.tts.title": "ເລື່ອນອັດຕະໂນມັດ ແລະ ອ່ານອອກສຽງ",
      "features.tts.body": "ເລື່ອນອັດຕະໂນມັດສຳລັບການອ່ານຍາວ ແລະ ອ່ານຄຳແປອອກສຽງແບບເລືອກໄດ້ພ້ອມປຸ່ມຄວບຄຸມສື່.",
      "features.script.title": "ອັກສອນປາລີ",
      "features.script.body": "ສະແດງປາລີໃນຫຼາຍອັກສອນ (ໂຣມັນ, ເທວະນາຄະຣີ, ໄທ, ມຽນມາ, ທິເບດ ແລະ ອື່ນໆ).",

      "online.title": "Tipiṭaka Translation (ອອນລາຍ)",
      "online.subtitle":
        "ວິທີຫຼັກໃນການອ່ານເນື້ອໃນຂອງໂຄງການນີ້ໃນເວັບບຣາວເຊີ ຄຽງຄູ່ກັບແອັບ OpenTipitaka.",
      "online.maintainer": "ດູແລໂດຍ ພຣະ Ariyavaṃsa (Pa-Auk).",
      "online.cta": "ເປີດເວັບໄຊ",

      "download.title": "ດາວໂຫຼດ ແລະ ຂໍ້ມູນ",
      "download.quickStart.title": "ເລີ່ມຕົ້ນໄວ",
      "download.quickStart.s1":
        "ຕິດຕັ້ງຈາກ App Store (iPhone, iPad, Mac) ຫຼື Google Play (Android). ສຳລັບ Windows ໃຫ້ໃຊ້ Microsoft Store ຫຼື ລິ້ງໂຟນເດີ Tipitaka ດ້ານລຸ່ມ. ສຳລັບ Linux ໃຫ້ດາວໂຫຼດຕົວຕິດຕັ້ງຈາກໂຟນເດີ Tipitaka ຂອງ Pa-Auk.",
      "download.quickStart.s2": "ໃນການເປີດຄັ້ງທຳອິດ, ເລືອກພາສາອິນເຕີເຟດຂອງແອັບ.",
      "download.quickStart.s3": "ເມື່ອອອນລາຍ, ດາວໂຫຼດຖານຂໍ້ມູນຄຳແປຈາກໃນແອັບ.",
      "download.dataHelp.title":
        "ຕົວຕິດຕັ້ງ Android/Linux, ຖານຂໍ້ມູນຄຳແປ, ເອກະສານ EPUB/PDF/TXT",
      "download.dataHelp.documentsCta": "ດາວໂຫຼດເອກະສານ EPUB, PDF ແລະ TXT",
      "download.dataHelp.apkIntro":
        "Android APK ແລະ ຕົວຕິດຕັ້ງ Windows/Linux ຖືກເຜີຍແຜ່ໃນເວັບໄຟລ໌ຂອງສະມາຄົມ Pa-Auk (ລິ້ງດ້ານລຸ່ມ). ຖ້າຕິດຕັ້ງຈາກຮ້ານແອັບບໍ່ໄດ້, ໃຫ້ໃຊ້ລິ້ງນັ້ນເພື່ອດາວໂຫຼດ ແລະ ຕິດຕັ້ງ.",
      "download.dataHelp.apkCta": "ດາວໂຫຼດ Android APK · ຕົວຕິດຕັ້ງ Windows · Linux",
      "download.dataHelp.manualIntro":
        "ຖ້າການດາວໂຫຼດຖານຂໍ້ມູນໃນແອັບລົ້ມເຫຼວ, ໃຊ້ລິ້ງດ້ານລຸ່ມເພື່ອດາວໂຫຼດຊຸດຂໍ້ມູນຄຳແປດ້ວຍຕົນເອງ ແລ້ວນຳເຂົ້າໃນແອັບ.",
      "download.dataHelp.manualCta": "ດາວໂຫຼດຖານຂໍ້ມູນຄຳແປ",
      "download.platforms.title": "ແພລດຟອມ",
      "download.platforms.rowApple.k": "iPhone · iPad · Mac",
