      "faq.title": "ຄຳຖາມທີ່ພົບເລື້ອຍ",
      "faq.q1.q": "ຄຳແປໄດ້ຖືກກວດແກ້ຄົບຖ້ວນແລ້ວບໍ?",
      "faq.q1.a":
        "ຍັງ. ຄຳແປຫຼາຍສ່ວນຖືກສ້າງໂດຍ AI ແລະ ກຳລັງຖືກປັບປຸງຕໍ່ໄປ. ແອັບເຊີນທຸກຄົນໃຫ້ຊ່ວຍກວດແກ້ ແລະ ປັບຄຳສັບໃຫ້ສອດຄ່ອງຂຶ້ນຕາມເວລາ.",
      "faq.q2.q": "ຂ້ອຍສາມາດຮ່ວມແກ້ໄຂໄດ້ບໍ?",
      "faq.q2.a": "ໄດ້. ລົງທະບຽນ ແລະ ເຂົ້າລະບົບ, ຈາກນັ້ນດັບເບິນຄລິກຄຳແປຂອງຫຍໍ້ໜ້າເພື່ອແກ້ໄຂ ແລະ ສົ່ງເຂົ້າການກວດ.",
      "faq.q3.q": "ໃຊ້ອອບລາຍໄດ້ບໍ?",
      "faq.q3.a": "ໄດ້. ເນື້ອໃນຖືກເກັບໄວ້ໃນຖານຂໍ້ມູນ SQLite ທ້ອງຖິ່ນ. ທ່ານສາມາດນຳເຂົ້າຖານຂໍ້ມູນ ແລະ ອັບເດດເມື່ອອອນລາຍ.",
      "faq.q4.q": "ຖ້າດາວໂຫຼດຖານຂໍ້ມູນໃນແອັບບໍ່ສຳເລັດ ຄວນເຮັດແນວໃດ?",
      "faq.q4.a":
        "ໃຊ້ລິ້ງດາວໂຫຼດຖານຂໍ້ມູນຄຳແປ, ເຊິ່ງເປີດໂຟນເດີໂດຍກົງ, ເພື່ອດາວໂຫຼດຊຸດຂໍ້ມູນ ແລ້ວນຳເຂົ້າໃນແອັບ. ໃຊ້ລິ້ງດາວໂຫຼດຕົວຕິດຕັ້ງສຳລັບ Android APK ແລະ ຕົວຕິດຕັ້ງ Windows/Linux ເມື່ອບໍ່ໃຊ້ຮ້ານແອັບ.",

      "footer.tagline": "ການອ່ານ ແລະ ກວດແກ້ພຣະໄຕປິດົກພາສາປາລີພ້ອມຄຳແປຫຼາຍພາສາ.",
